  function watchClock(){const sec=Math.ceil(Math.max(0,WatchMath.limit-(watch?.elapsed||0)));$('watchClock').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}
