  function open(){if(running){toast('Yerleşimi açmadan önce seans sayacını duraklat.');return}returnFocus=document.activeElement;draft=GoZ.normalizeLayout(state.layout);locked=draft.saved;overlay.hidden=false;document.querySelector('main').inert=true;document.querySelector('header').inert=true;document.body.classList.add('fit-open');controls();draw();const aspect=window.innerWidth/window.innerHeight;status(!landscape()?'Telefonu yatay çevir.':draft.saved&&Math.abs(draft.aspect-aspect)>.12?'Ekran oranı değişmiş. Yerleşimi yeniden kontrol et.':draft.saved?'Kaydedilmiş konumlar yüklendi ve kilitlendi.':'Daireleri sürükle, sonra kaydet.');requestWake();$('closePreview').focus()}
