  $('resetLayout').onclick=()=>{draft=GoZ.normalizeLayout(null);controls();draw();status('Ortalandı; bu yerleşimi saklamak için Kaydet kullan.')};$('fitSize').oninput=()=>{draft.size=Number($('fitSize').value)/100;controls();draw();status('Ortak boyut değişti · henüz kaydedilmedi')};
